import { ColorPicker, parse, rgbToHsv } from "march/ui"

// ruh hâli yüzüğü: bir renk seç, yüzük o renge boyanır ve tonuna göre bir ruh hâli söyler
const MOODS = [[30, "Heyecanlı"], [70, "Neşeli"], [160, "Huzurlu"], [250, "Düşünceli"], [320, "Romantik"], [360, "Heyecanlı"]] as const
const moodOf = (color: string) => {
  const rgb = parse(color)
  const hue = rgb ? rgbToHsv(rgb).h : 0
  return MOODS.find(([max]) => hue < max)?.[1] ?? "Heyecanlı"
}

export function MoodRing() {
  let $color = "#f2801f"
  return <div sx={{ flex: ["row", "wrap", "center"], gap: 4 }}>
    <ColorPicker bind:value={$color} alpha={false} palettes={false} contrast={false} formats={false} aria-label="Yüzüğün rengi" />
    <div sx={{ flex: ["col", "center"], gap: 2 }}>
      <div style={{ width: "6rem", height: "6rem", borderRadius: "50%", border: `0.75rem solid ${$color}` }} />
      <b sx={{ text: "lg" }}>{moodOf($color)}</b>
    </div>
  </div>
}

import { ColorPicker, Toggle } from "march/ui"
import { droplet } from "march/icons"

// ColorPicker'ın bütün özellikleri: değer (bind:value) ve onChange, saydamlık, biçim, kendi paletin, son seçilenler,
// göz damlası ve kendi ikonu, kontrast, eski / yeni önizleme, biçim seçici, değer alanı, kendi metinlerin, sınıf,
// salt okunur / devre dışı, ad (name) ve erişilebilir ad
const LABELS = { picker: "Renk laboratuvarı", hue: "Ton", opacity: "Saydamlık", value: "Renk değeri", format: "Biçim", contrast: "Okunurluk", onWhite: "beyazda", onBlack: "siyahta", recent: "Az önce" }

export function ColorPickerLab() {
  let $color = "#a3338c"
  let $changes = 0
  let $locked = false
  let $off = false
  return <div sx={{ flex: "col", gap: 3 }}>
    <div sx={{ flex: ["row", "wrap"], gap: 3 }}>
      <Toggle label="Kilitle (salt okunur)" bind:value={$locked} />
      <Toggle label="Devre dışı" bind:value={$off} />
      <span sx={{ text: "sm" }}>Değer: <code>{$color}</code> · değişiklik: {$changes}</span>
    </div>
    <ColorPicker
      bind:value={$color}
      onChange={() => $changes++}
      alpha
      format="hsl"
      palettes={[{ label: "Gün batımı", colors: ["#ff7e5f", "#feb47b", "#6a3093"] }, { label: "Tema", colors: ["primary", "success", "danger"] }]}
      recent={3}
      eyedropper
      eyedropperIcon={droplet}
      contrast
      preview
      formats
      input
      labels={LABELS}
      class="lab-cp"
      readonly={$locked}
      disabled={$off}
      name="accent"
      aria-label="Vurgu rengi"
    />
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { ColorPickerLab } from "./ColorPickerLab.tsx"

// ColorPickerLab'in testleri: kaydedince Testler sekmesinde çalışır
test("değer alanına yazılan renk değeri ve sayacı günceller", async () => {
  const s = renderTest(() => <ColorPickerLab />)
  await s.type("Vurgu rengi", "#ff0000")
  // biçim hsl: değer hsl olarak yazılır
  expect(s.sees("hsl(0")).toBe(true)
  expect(s.sees("değişiklik: 1")).toBe(true)
})

test("kendi paletindeki bir renge basınca seçilir", async () => {
  const s = renderTest(() => <ColorPickerLab />)
  await s.click("#6a3093")
  expect(s.sees("değişiklik: 1")).toBe(true)
  expect(s.sees("Gün batımı")).toBe(true)
})

test("kendi metinleri: ton kaydırıcısı ve kontrast satırı", () => {
  const s = renderTest(() => <ColorPickerLab />)
  expect(s.find("Ton")).not.toBe(null)
  expect(s.sees("beyazda")).toBe(true)
  expect(s.get(".lab-cp")?.getAttribute("aria-label")).toBe("Vurgu rengi")
})

test("salt okunurken palet seçimi değeri değiştirmez", async () => {
  const s = renderTest(() => <ColorPickerLab />)
  await s.click(s.find("Kilitle (salt okunur)")!.closest("label")!.querySelector("[role=switch]")!)
  expect(s.get(".lab-cp")?.className).toContain("is-readonly")
  await s.click("#6a3093")
  expect(s.sees("değişiklik: 0")).toBe(true)
})
